// ════════════════════════════════════════════════════════
// ⚙️  CRYPTO PRICE ALERT BOT — ALL CONFIGURATION HERE
// ════════════════════════════════════════════════════════
// This is the ONLY node you need to edit to get started.
// ════════════════════════════════════════════════════════

// ── STEP 1: Telegram Chat ID ─────────────────────────────
// Message @userinfobot on Telegram to get your Chat ID.
const TELEGRAM_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID_HERE';

// ── STEP 2: Google Sheets ID (optional) ──────────────────
// Create a Google Sheet and paste its ID from the URL:
// https://docs.google.com/spreadsheets/d/{SHEET_ID}/edit
// Leave as placeholder to disable Sheets logging.
const GOOGLE_SHEET_ID = 'YOUR_GOOGLE_SHEET_ID_HERE';

// ── STEP 3: Your Crypto Watchlist ────────────────────────
// Add or remove assets. Find CoinGecko IDs at:
// https://api.coingecko.com/api/v3/coins/list
const watchlist = [
  {
    symbol: 'bitcoin',        // CoinGecko coin ID (must be lowercase)
    display: 'BTC',           // Short label shown in Telegram alerts
    threshold: 75000,         // USD price that triggers the alert
    direction: 'below',       // 'above' or 'below'
    cooldownMinutes: 60,      // Minimum minutes between repeated alerts
    holdings: 0,              // Coins you own — set 0 to disable portfolio tracking
    priceChangePct: 5,        // Alert if price moves ±5% since last check (0 = off)
    useRSI: true,             // true = enable 14-period RSI confirmation filter
    rsiOversold: 30,          // RSI below this is oversold (used as filter)
    rsiOverbought: 70         // RSI above this is overbought (used as filter)
  },
  {
    symbol: 'ethereum',
    display: 'ETH',
    threshold: 2000,
    direction: 'above',
    cooldownMinutes: 30,
    holdings: 0,
    priceChangePct: 5,
    useRSI: true,
    rsiOversold: 30,
    rsiOverbought: 70
  },
  {
    symbol: 'solana',
    display: 'SOL',
    threshold: 90,
    direction: 'below',
    cooldownMinutes: 60,
    holdings: 0,
    priceChangePct: 10,
    useRSI: false,
    rsiOversold: 30,
    rsiOverbought: 70
  }
];

// ── Internal: pass config fields to each item ────────────
return watchlist.map(asset => ({
  json: {
    ...asset,
    telegramChatId: TELEGRAM_CHAT_ID,
    googleSheetId: GOOGLE_SHEET_ID
  }
}));

// Merge asset config (from Loop Assets) with the CoinGecko API response.
// Handles API errors gracefully and computes portfolio value.
const assetConfig = $('Loop Over Assets').first().json;
const apiResponse = $input.first().json;
const symbol = assetConfig.symbol;

// Guard: empty or failed API response
if (!apiResponse || typeof apiResponse !== 'object' || Object.keys(apiResponse).length === 0) {
  return [{ json: {
    symbol,
    display: assetConfig.display,
    hasError: true,
    errorMessage: `CoinGecko returned empty response for '${symbol}'. Check rate limits or coin ID.`
  }}];
}

const coinData = apiResponse[symbol];

// Guard: symbol not found in response
if (!coinData || typeof coinData.usd === 'undefined') {
  return [{ json: {
    symbol,
    display: assetConfig.display,
    hasError: true,
    errorMessage: `Symbol '${symbol}' not found on CoinGecko. Verify the coin ID.`
  }}];
}

const currentPrice = Number(coinData.usd);
const holdings = Number(assetConfig.holdings || 0);
const portfolioValue = holdings > 0
  ? parseFloat((currentPrice * holdings).toFixed(2))
  : null;

return [{ json: {
  // Asset identity
  symbol: assetConfig.symbol,
  display: assetConfig.display,
  chartUrl: `https://www.coingecko.com/en/coins/${assetConfig.symbol}`,
  // Alert configuration
  threshold: Number(assetConfig.threshold),
  direction: assetConfig.direction,
  cooldownMinutes: Number(assetConfig.cooldownMinutes),
  priceChangePct: Number(assetConfig.priceChangePct || 0),
  useRSI: Boolean(assetConfig.useRSI),
  rsiOversold: Number(assetConfig.rsiOversold || 30),
  rsiOverbought: Number(assetConfig.rsiOverbought || 70),
  // Portfolio
  holdings,
  portfolioValue,
  // Credentials / config pass-through
  telegramChatId: assetConfig.telegramChatId,
  googleSheetId: assetConfig.googleSheetId,
  // Live market data
  currentPrice,
  change24h: parseFloat(Number(coinData.usd_24h_change || 0).toFixed(2)),
  volume24h: Number(coinData.usd_24h_vol || 0),
  marketCap: Number(coinData.usd_market_cap || 0),
  // Metadata
  currentTimestamp: Date.now(),
  hasError: false
}}];

// Load per-asset persistent state from workflow static data.
// Static data survives between executions when the workflow is activated.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
const { symbol } = item;

// Initialise top-level store if first-ever execution
if (!staticData.assets) staticData.assets = {};

// Initialise per-asset state if this coin was never seen before
if (!staticData.assets[symbol]) {
  staticData.assets[symbol] = {
    lastPrice: null,
    lastAlertAt: null,
    avgVolume: null,
    volumeHistory: []
  };
}

const assetState = staticData.assets[symbol];
const nowTimestamp = Date.now();

return [{ json: {
  ...item,
  lastPrice: assetState.lastPrice,
  lastAlertAt: assetState.lastAlertAt,
  avgVolume: assetState.avgVolume || null,
  nowTimestamp,
  isFirstRun: assetState.lastPrice === null
}}];

// First run for this asset — store the baseline price so future cycles
// can detect changes. No alert is sent on the first run.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
if (!staticData.assets) staticData.assets = {};
staticData.assets[item.symbol] = {
  lastPrice: item.currentPrice,
  lastAlertAt: null,
  avgVolume: null,
  volumeHistory: []
};
return [{ json: item }];

// Calculate 14-period RSI using Wilder's Smoothing Method.
// Uses CoinGecko daily close prices from the /market_chart endpoint.
// Falls back gracefully if data is unavailable or useRSI is false.
const assetData = $('Load Asset State').first().json;
const marketChart = $input.first().json;

function calculateRSI(prices, period) {
  if (!prices || prices.length < period + 1) return null;
  let gains = 0, losses = 0;
  // Initial average over first `period` changes
  for (let i = 1; i <= period; i++) {
    const diff = prices[i] - prices[i - 1];
    if (diff >= 0) gains += diff; else losses += Math.abs(diff);
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  // Wilder's smoothing for remaining periods
  for (let i = period + 1; i < prices.length; i++) {
    const diff = prices[i] - prices[i - 1];
    const g = diff >= 0 ? diff : 0;
    const l = diff < 0 ? Math.abs(diff) : 0;
    avgGain = (avgGain * (period - 1) + g) / period;
    avgLoss = (avgLoss * (period - 1) + l) / period;
  }
  if (avgLoss === 0) return 100;
  return parseFloat((100 - (100 / (1 + avgGain / avgLoss))).toFixed(2));
}

let rsi = null;
let rsiLabel = 'N/A';

if (assetData.useRSI && marketChart && Array.isArray(marketChart.prices) && marketChart.prices.length > 0) {
  const closes = marketChart.prices.map(p => p[1]);
  rsi = calculateRSI(closes, 14);
  if (rsi !== null) {
    rsiLabel = rsi > 70 ? '🔴 Overbought' : rsi < 30 ? '🟢 Oversold' : '⚪ Neutral';
  }
}

return [{ json: { ...assetData, rsi, rsiLabel } }];

// Evaluate all three alert condition types and produce a decision.
// Returns shouldAlert (bool) and triggerReasons (string array).
const item = $input.first().json;
const {
  currentPrice, lastPrice, threshold, direction,
  priceChangePct, rsi, rsiOversold, rsiOverbought,
  useRSI, volume24h, avgVolume
} = item;

const triggerReasons = [];

// ── Condition 1: Fixed Price Threshold ─────────────────────
const thresholdMet =
  (direction === 'above' && currentPrice > threshold) ||
  (direction === 'below' && currentPrice < threshold);
if (thresholdMet) {
  const dir = direction === 'above' ? 'Above 📈' : 'Below 📉';
  triggerReasons.push(`Price ${dir} $${threshold.toLocaleString('en-US')}`);
}

// ── Condition 2: Price % Change Since Last Check ───────────
let pctChangeMet = false;
if (priceChangePct > 0 && lastPrice && lastPrice > 0) {
  const actualPct = Math.abs((currentPrice - lastPrice) / lastPrice * 100);
  if (actualPct >= priceChangePct) {
    pctChangeMet = true;
    const signedPct = ((currentPrice - lastPrice) / lastPrice * 100).toFixed(2);
    const emoji = currentPrice > lastPrice ? '📈' : '📉';
    triggerReasons.push(`${emoji} Price moved ${signedPct}% (trigger: ±${priceChangePct}%)`);
  }
}

// ── Condition 3: Volume Spike (≥2× rolling 7-period average) ─
let volumeSpikeMet = false;
if (avgVolume && avgVolume > 0 && volume24h > 0) {
  const ratio = volume24h / avgVolume;
  if (ratio >= 2) {
    volumeSpikeMet = true;
    triggerReasons.push(`🔊 Volume spike: ${ratio.toFixed(1)}× average`);
  }
}

// ── RSI Filter: suppress alerts at extremes ─────────────────
// RSI is a FILTER, not a trigger. It prevents chasing extremes.
let rsiConfirms = true;
if (useRSI && rsi !== null) {
  if (direction === 'above' && rsi > rsiOverbought) rsiConfirms = false; // overbought, don't chase
  if (direction === 'below' && rsi < rsiOversold)   rsiConfirms = false; // oversold, don't short
}

const shouldAlert =
  thresholdMet ||
  volumeSpikeMet ||
  (pctChangeMet && rsiConfirms);

const priceChangeFromLast = (lastPrice && lastPrice > 0)
  ? parseFloat(((currentPrice - lastPrice) / lastPrice * 100).toFixed(2))
  : null;

return [{ json: {
  ...item,
  shouldAlert,
  triggerReasons,
  triggerReasonsStr: triggerReasons.join(' | '),
  rsiConfirms,
  priceChangeFromLast
}}];

// Build a rich, human-readable Telegram alert message using Markdown.
// Conditionally includes RSI, portfolio value, and % change sections.
const item = $input.first().json;

const fmt = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const changeSign = item.change24h >= 0 ? '+' : '';
const changeEmoji = item.change24h >= 0 ? '📈' : '📉';
const alertDate = new Date(item.nowTimestamp).toUTCString();

const lines = [
  `🚨 *${item.display} Alert Triggered!*`,
  ``,
  `💰 *Current Price:* $${fmt(item.currentPrice)}`,
  `${changeEmoji} *24h Change:* ${changeSign}${item.change24h}%`,
];

// Price change since last check (if available)
if (item.priceChangeFromLast !== null) {
  const s = item.priceChangeFromLast >= 0 ? '+' : '';
  lines.push(`📊 *Change Since Last Check:* ${s}${item.priceChangeFromLast}%`);
}

// RSI reading (if RSI filter is enabled)
if (item.useRSI && item.rsi !== null) {
  lines.push(`📐 *RSI (14):* ${item.rsi} — ${item.rsiLabel}`);
}

// Portfolio value (if holdings are configured)
if (item.portfolioValue !== null) {
  lines.push(`💼 *Portfolio Value:* $${fmt(item.portfolioValue)} (${item.holdings} ${item.display})`);
}

// Trigger reason breakdown
lines.push(``, `🎯 *Triggered By:*`);
(item.triggerReasons || []).forEach(r => lines.push(`  • ${r}`));

// RSI override notice
if (!item.rsiConfirms) {
  lines.push(``, `⚠️ _RSI filter was overridden — multiple conditions met_`);
}

lines.push(``, `📊 [View Chart on CoinGecko](${item.chartUrl})`);

return [{ json: { ...item, alertMessage: lines.join('\n'), alertDate } }];

// Save state after a successful alert.
// Updates BOTH lastPrice AND lastAlertAt (starts the cooldown timer).
// Also maintains a rolling 7-period volume history for spike detection.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
if (!staticData.assets) staticData.assets = {};

const existing = staticData.assets[item.symbol] || {};
const volumeHistory = existing.volumeHistory ? [...existing.volumeHistory] : [];
if (item.volume24h > 0) {
  volumeHistory.push(item.volume24h);
  if (volumeHistory.length > 7) volumeHistory.shift(); // keep last 7 only
}
const avgVolume = volumeHistory.length > 0
  ? volumeHistory.reduce((a, b) => a + b, 0) / volumeHistory.length
  : null;

staticData.assets[item.symbol] = {
  lastPrice: item.currentPrice,
  lastAlertAt: item.nowTimestamp,  // ← this starts the cooldown
  avgVolume,
  volumeHistory
};

return [{ json: item }];

// Save the latest price WITHOUT resetting the cooldown timer.
// Used when: no condition was met, or the cooldown hasn't expired yet.
// Also updates the rolling volume history for spike detection.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
if (!staticData.assets) staticData.assets = {};

const existing = staticData.assets[item.symbol] || {};
const volumeHistory = existing.volumeHistory ? [...existing.volumeHistory] : [];
if (item.volume24h > 0) {
  volumeHistory.push(item.volume24h);
  if (volumeHistory.length > 7) volumeHistory.shift();
}
const avgVolume = volumeHistory.length > 0
  ? volumeHistory.reduce((a, b) => a + b, 0) / volumeHistory.length
  : null;

staticData.assets[item.symbol] = {
  lastPrice: item.currentPrice,
  lastAlertAt: existing.lastAlertAt || null,  // ← preserved, not reset
  avgVolume,
  volumeHistory
};

return [{ json: item }];

// ── Daily Digest Configuration ─────────────────────────────
// Keep this watchlist in sync with the main Watchlist Config node.
// Only symbol, display, and holdings are needed here.

const TELEGRAM_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID_HERE';

const watchlist = [
  { symbol: 'bitcoin',  display: 'BTC', holdings: 0 },
  { symbol: 'ethereum', display: 'ETH', holdings: 0 },
  { symbol: 'solana',   display: 'SOL', holdings: 0 }
];

const allSymbols = watchlist.map(a => a.symbol).join(',');

return [{ json: { allSymbols, watchlist, telegramChatId: TELEGRAM_CHAT_ID } }];

// Compile the daily digest message from bulk price data and Fear & Greed index.
// Gracefully handles unavailable Fear & Greed data.
const digestConfig = $('Configure Daily Digest').first().json;
const pricesData = $('Retrieve All Crypto Prices').first().json;
const fngResponse = $input.first().json;

const fmt = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const dateStr = new Date().toUTCString().replace(' GMT', ' UTC');

// Fear & Greed block (optional — fails silently if API is down)
let fngLine = '';
try {
  if (fngResponse && fngResponse.data && fngResponse.data[0]) {
    const v = Number(fngResponse.data[0].value);
    const label =
      v < 25 ? '😱 Extreme Fear' :
      v < 45 ? '😨 Fear' :
      v < 55 ? '😐 Neutral' :
      v < 75 ? '😄 Greed' :
               '🤑 Extreme Greed';
    fngLine = `\n📊 *Fear & Greed:* ${v}/100 — ${label}`;
  }
} catch (_) {}

const lines = [
  `📅 *Daily Crypto Summary*`,
  `_${dateStr}_`,
  fngLine,
  ``,
  `━━━━━━━━━━━━━━━━━`
];

let totalPortfolio = 0;

for (const asset of digestConfig.watchlist) {
  const coin = pricesData && pricesData[asset.symbol];
  if (!coin) { lines.push(`• *${asset.display}* — data unavailable`); continue; }
  const price = Number(coin.usd);
  const chg = parseFloat(Number(coin.usd_24h_change || 0).toFixed(2));
  const sign = chg >= 0 ? '+' : '';
  const emoji = chg >= 0 ? '📈' : '📉';
  const portfolioStr = asset.holdings > 0 ? ` | 💼 $${fmt(price * asset.holdings)}` : '';
  if (asset.holdings > 0) totalPortfolio += price * asset.holdings;
  lines.push(`${emoji} *${asset.display}:* $${fmt(price)} (${sign}${chg}%)${portfolioStr}`);
}

lines.push(`━━━━━━━━━━━━━━━━━`);
if (totalPortfolio > 0) {
  lines.push(`💰 *Total Portfolio:* $${fmt(totalPortfolio)}`, ``);
}
lines.push(`🤖 _Crypto Price Alert Bot_`);

return [{ json: {
  telegramChatId: digestConfig.telegramChatId,
  digestMessage: lines.join('\n')
}}];

// Parse incoming Telegram message and resolve ticker aliases to CoinGecko IDs.
// Handles commands in formats: /price, /price@botname, /price btc, /price bitcoin
const msg = $input.first().json.message;

if (!msg || !msg.text) {
  return [{ json: { commandType: 'unknown', symbol: '', chatId: String(msg?.chat?.id || ''), displayArg: '' } }];
}

const raw = (msg.text || '').trim().toLowerCase();
const chatId = String(msg.chat.id);
const parts = raw.split(/\s+/);
const cmdRaw = parts[0].replace(/^\//, '').split('@')[0]; // strip / and @botname
const arg = (parts[1] || '').trim();

// Ticker alias → CoinGecko coin ID mapping
const aliases = {
  btc: 'bitcoin', eth: 'ethereum', sol: 'solana',
  ada: 'cardano', dot: 'polkadot', matic: 'matic-network',
  avax: 'avalanche-2', link: 'chainlink', doge: 'dogecoin',
  xrp: 'ripple', bnb: 'binancecoin', uni: 'uniswap',
  atom: 'cosmos', ltc: 'litecoin'
};

const resolvedSymbol = aliases[arg] || arg;

return [{ json: {
  commandType: cmdRaw,
  symbol: resolvedSymbol,
  displayArg: arg.toUpperCase(),
  chatId,
  rawText: raw
}}];

// Format the price reply for a /price command.
// Provides a helpful fallback message if the coin ID is not found.
const cmdData = $('Decode Telegram Message').first().json;
const priceData = $input.first().json;
const symbol = cmdData.symbol;
const coin = priceData && priceData[symbol];

const fmt = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

if (!coin || !coin.usd) {
  return [{ json: {
    chatId: cmdData.chatId,
    replyMessage: [
      `❓ Could not find price for *${cmdData.displayArg || symbol}*.`,
      ``,
      `Try the full CoinGecko coin ID:`,
      `\`/price bitcoin\``,
      ``,
      `Or browse IDs at: coingecko.com/en/coins`
    ].join('\n')
  }}];
}

const price = Number(coin.usd);
const chg = parseFloat(Number(coin.usd_24h_change || 0).toFixed(2));
const sign = chg >= 0 ? '+' : '';
const emoji = chg >= 0 ? '📈' : '📉';
const mcapLine = coin.usd_market_cap
  ? `\n🏦 *Market Cap:* $${fmt(coin.usd_market_cap)}`
  : '';

const msg = [
  `💰 *${cmdData.displayArg || symbol.toUpperCase()} Live Price*`,
  ``,
  `*Price:* $${fmt(price)}`,
  `${emoji} *24h Change:* ${sign}${chg}%`,
  mcapLine,
  ``,
  `[View on CoinGecko](https://www.coingecko.com/en/coins/${symbol})`
].join('\n');

return [{ json: { chatId: cmdData.chatId, replyMessage: msg } }];
